from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    result = []

    def add_months(year, month, offset):
        total = year * 12 + (month - 1) + offset
        return total // 12, total % 12 + 1

    if parts[0] == "DAILY":
        step = int(parts[1])
        current = start_date
        for _ in range(count):
            result.append(current.isoformat())
            current += timedelta(days=step)

    elif parts[0] == "WEEKLY":
        step = int(parts[1])
        weekday_map = {
            "MO": 0, "TU": 1, "WE": 2, "TH": 3,
            "FR": 4, "SA": 5, "SU": 6,
        }
        weekdays = sorted(weekday_map[x] for x in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(result) < count:
            if week_index % step == 0:
                for weekday in weekdays:
                    candidate = week_start + timedelta(days=weekday)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                        if len(result) == count:
                            break
            week_index += 1
            week_start += timedelta(days=7)

    elif parts[0] == "MONTHLY":
        step = int(parts[1])
        base_year, base_month = start_date.year, start_date.month
        month_index = 0

        if len(parts) == 3:
            day_value = int(parts[2])

            while len(result) < count:
                year, month = add_months(base_year, base_month, month_index)
                last_day = calendar.monthrange(year, month)[1]
                day = last_day if day_value == -1 else day_value

                if day <= last_day:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())

                month_index += step
        else:
            nth = int(parts[2])
            weekday_map = {
                "MO": 0, "TU": 1, "WE": 2, "TH": 3,
                "FR": 4, "SA": 5, "SU": 6,
            }
            target_weekday = weekday_map[parts[3]]

            while len(result) < count:
                year, month = add_months(base_year, base_month, month_index)
                last_day = calendar.monthrange(year, month)[1]

                if nth == -1:
                    candidate = date(year, month, last_day)
                    candidate -= timedelta(
                        days=(candidate.weekday() - target_weekday) % 7
                    )
                else:
                    candidate = date(year, month, 1)
                    candidate += timedelta(
                        days=(target_weekday - candidate.weekday()) % 7 + 7 * (nth - 1)
                    )
                    if candidate.month != month:
                        candidate = None

                if candidate is not None and candidate >= start_date:
                    result.append(candidate.isoformat())

                month_index += step

    else:  # YEARLY
        step = int(parts[1])
        month, day = map(int, parts[2].split("-"))
        year = start_date.year

        while len(result) < count:
            try:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
            except ValueError:
                pass
            year += step

    return result
